#!/usr/bin/env bash\nset -e\n\n# Initialize Terraform without a remote backend (local only)\nterraform init -backend=false > /dev/null\n\n# Validate the configuration syntax\nterraform validate\n\n# Perform a dry‑run plan; skip refresh to avoid real provider calls\nterraform plan -input=false -refresh=false -out=plan.out > /dev/null\n\n# Mock rationale: The test assumes provider plugins are present and no real AWS calls are made.\n# Verify that the bucket name appears in the generated plan.\nEXPECTED_BUCKET_NAME=${TF_VAR_bucket_name:-example-safehouse}\nif ! terraform show -no-color plan.out | grep -q "$EXPECTED_BUCKET_NAME"; then\n  echo "Bucket name \"$EXPECTED_BUCKET_NAME\" not found in plan"\n  exit 1\nfi\n\necho "All checks passed"\n
